Tests.EqualCheck("highlight literal word in line", "hello \033[31mworld\033[0m", highlightSingleMatch("hello world", "world"))
Tests.EqualCheck("highlight first digits in line", "user \033[31m42\033[0m and 100", highlightSingleMatch("user 42 and 100", `\d+`))
Tests.EqualCheck("non-matching pattern returns original line", "apple pie", highlightSingleMatch("apple pie", "orange"))
Tests.EqualCheck("highlight at start of line", "\033[31mstart\033[0m of line", highlightSingleMatch("start of line", "^start"))
Tests.EqualCheck("highlight at end of line", "end of \033[31mline\033[0m", highlightSingleMatch("end of line", "line$"))
Tests.EqualCheck("highlight with character class", "item: \033[31m[A-1]\033[0m ok", highlightSingleMatch("item: [A-1] ok", `\[[A-Z]-\d\]`))
Tests.EqualCheck("highlight with alternation first branch", "I like \033[31mcats\033[0m and dogs", highlightSingleMatch("I like cats and dogs", "cats|dogs"))
Tests.EqualCheck("highlight with alternation second branch", "I like \033[31mdogs\033[0m", highlightSingleMatch("I like dogs", "cats|dogs"))
Tests.EqualCheck("highlight backreference pattern", "\033[31mcat and cat\033[0m here", highlightSingleMatch("cat and cat here", `(\w+) and \1`))
Tests.EqualCheck("empty pattern returns line unchanged", "unchanged", highlightSingleMatch("unchanged", ""))
Tests.EqualCheck("empty line returns empty line", "", highlightSingleMatch("", "word"))
Tests.EqualCheck("only first match is highlighted", "first \033[31mfoo\033[0m second foo", highlightSingleMatch("first foo second foo", "foo"))
Tests.EqualCheck("highlight quantifier word", "call \033[31mhelper\033[0m now", highlightSingleMatch("call helper now", `\w{6}`))
Tests.EqualCheck("highlight single character", "\033[31mx\033[0myz", highlightSingleMatch("xyz", "x"))
Tests.EqualCheck("highlight entire line match", "\033[31mcomplete\033[0m", highlightSingleMatch("complete", "^complete$"))
Tests.EqualCheck("no match with anchors returns unchanged", "good start", highlightSingleMatch("good start", "^start"))
